+  const eligible = new Set(movies
+    .map((movie) => movie.id)
+    .filter((id) => Number.isInteger(id) && id >= 0 && id < rows && !excluded.has(id)));
+  const count = Math.min(Math.floor(K), eligible.size);
+  if (count <= 0) return [];
+
+  return tf.tidy(() => {
