+    const masked = tf.where(tf.tensor1d(mask, "bool"), scores, tf.fill([rows], -Infinity));
+    const { values, indices } = tf.topk(masked, count, true);
+    const ids = indices.dataSync();
+    const rankedScores = values.dataSync();
+    return Array.from(ids, (movieId, index) => ({
+      movieId,
+      title: movieTitle(movieId),
+      score: rankedScores[index],
+    })).filter((r) => eligible.has(r.movieId));
+  });
 }
