+  const baseI = tf.randomNormal(model.itemFactors.shape, 0, .05, 'float32', seeds[1]);
+  const userIds = Int32Array.from(trainSet, r => r.userId);
+  const itemIds = Int32Array.from(trainSet, r => r.movieId);
+  const targets = Float32Array.from(trainSet, r => r.rating);
+  const norm = t => {
+    const a = t.dataSync();
+    let sum = 0, maxAbs = 0;
+    for (const v of a) { sum += v * v; maxAbs = Math.max(maxAbs, Math.abs(v)); }
+    return { norm: Math.sqrt(sum), maxAbs };
+  };
+  const results = [];
+  try {
+    for (const variant of ['A_global_sum', 'B_batch_mean_row_sum', 'C_global_element_mean', 'D_batch_element_mean']) {
+      model.userFactors.assign(baseU);
+      model.itemFactors.assign(baseI);
+      const initial = { user: norm(model.userFactors), item: norm(model.itemFactors) };
+      const before = tf.memory().numTensors;
+      const optimizer = tf.train.adam(.01);
+      const history = [];
+      const started = performance.now();
+      try {
+        for (let epoch = 1; epoch <= 3; epoch++) {
+          for (let start = 0; start < trainSet.length; start += 64) {
+            const end = Math.min(start + 64, trainSet.length);
+            tf.tidy(() => {
+              const ui = tf.tensor1d(userIds.subarray(start, end), 'int32');
+              const ii = tf.tensor1d(itemIds.subarray(start, end), 'int32');
+              const y = tf.tensor1d(targets.subarray(start, end));
+              optimizer.minimize(() => {
+                const u = tf.gather(model.userFactors, ui);
+                const i = tf.gather(model.itemFactors, ii);
+                const pred = u.mul(i).sum(1).add(model.globalMean);
+                const mse = tf.losses.meanSquaredError(y, pred);
+                let penalty;
+                if (variant === 'A_global_sum') penalty = model.userFactors.square().sum().add(model.itemFactors.square().sum());
+                if (variant === 'B_batch_mean_row_sum') penalty = u.square().sum(1).add(i.square().sum(1)).mean();
+                if (variant === 'C_global_element_mean') penalty = model.userFactors.square().mean().add(model.itemFactors.square().mean());
+                if (variant === 'D_batch_element_mean') penalty = u.square().mean().add(i.square().mean());
+                return mse.add(penalty.mul(.05));
+              }, false, [model.userFactors, model.itemFactors]);
+            });
+          }
+          const recs = recommendTopK(620, 10);
+          const scores = recs.map(r => r.score);
+          const mean = scores.reduce((s,x) => s+x,0) / scores.length;
+          history.push({epoch, trainRMSE:computeRMSEFor(trainSet), valRMSE:computeRMSEFor(valSet),
+            user:norm(model.userFactors), item:norm(model.itemFactors),
+            recommendationScores:{min:Math.min(...scores),max:Math.max(...scores),std:Math.sqrt(scores.reduce((s,x)=>s+(x-mean)**2,0)/scores.length),distinct:new Set(scores).size}});
+        }
+      } finally { optimizer.dispose(); }
+      results.push({variant,initial,history,seconds:(performance.now()-started)/1000,tensorDelta:tf.memory().numTensors-before});
+    }
+  } finally { tf.dispose([baseU,baseI]); }
+  return {backend:tf.getBackend(),seeds,epochs:3,lr:.01,reg:.05,batchSize:64,factors:16,results};
+})()
